add_action( 'init', 'perfectpixel_disable_categories_tags', 99 );
add_action( 'template_redirect', 'perfectpixel_disable_categories_tags_archives', 1 );

function perfectpixel_disable_categories_tags_list() {
	$taxonomies = array();
	if ( 'no' !== strtolower( trim( '{{disable_post_categories}}' ) ) ) {
		$taxonomies[] = 'category';
	}
	if ( 'no' !== strtolower( trim( '{{disable_post_tags}}' ) ) ) {
		$taxonomies[] = 'post_tag';
	}
	return $taxonomies;
}

function perfectpixel_disable_categories_tags() {
	foreach ( perfectpixel_disable_categories_tags_list() as $taxonomy ) {
		unregister_taxonomy_for_object_type( $taxonomy, 'post' );
	}
}

function perfectpixel_disable_categories_tags_archives() {
	$list = perfectpixel_disable_categories_tags_list();
	if ( ( in_array( 'category', $list, true ) && is_category() ) || ( in_array( 'post_tag', $list, true ) && is_tag() ) ) {
		global $wp_query;
		$wp_query->set_404();
		status_header( 404 );
		nocache_headers();
	}
}
